def neighbors(grid, r, c, diagonal=False):
    rows, cols = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    if diagonal:
        directions.extend([(-1, -1), (-1, 1), (1, -1), (1, 1)])
    result = []

    for dr, dc in directions:
        nr, nc = r + dr, c + dc
        if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc]:
            result.append((nr, nc))

    return result

