    }
    if (amount <= 0) {
      throw new Error(`Amount ${amount} is not a positive number.`);
    }
    this.accounts[name] += amount;
  }

  balance(name) {
    if (!this.accounts[name]) {
      throw new Error(`Unknown account ${name}.`);
    }
    return this.accounts[name];
  }

  withdraw(name, amount) {
    if (!this.accounts[name]) {
      throw new Error(`Unknown account ${name}.`);
    }
    if (amount <= 0) {
      throw new Error(`Amount ${amount} is not a positive number.`);
    }
    if (this.accounts[name] < amount) {
      throw new Error(`Insufficient funds in account ${name}.`);
    }
    this.accounts[name] -= amount;
  }

  transfer(from, to, amount) {
    if (from === to) {
      throw new Error(`Cannot transfer to the same account.`);
    }
    if (!this.accounts[from] || !this.accounts[to]) {
      throw new Error(`Unknown account.`);
    }
    if (amount <= 0) {
      throw new Error(`Amount ${amount} is not a positive number.`);
    }
    if (this.accounts[from] < amount) {
      throw new Error(`Insufficient funds in account ${from}.`);
    }
    this.accounts[from] -= amount;
    this.accounts[to] += amount;
  }

  applyInterest(ratePct) {
    let totalInterest = 0;
    for (const [name, balance] of Object.entries(this.accounts)) {
      if (balance > 0) {
        const interest = Math.round(balance * ratePct / 100 * 100) / 100;
        this.accounts[name] += interest;
        totalInterest += interest;
      }
    }
    return totalInterest;
  }
};

